def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_c = 0
    my_c = 0
    cc = 0
    cd = 0
    dc = 0
    dd = 0
    for m, o in history:
        if m == 'C':
            my_c += 1
        else:
            pass
        if o == 'C':
            opp_c += 1
        if m == 'C' and o == 'C':
            cc += 1
        elif m == 'C' and o == 'D':
            cd += 1
        elif m == 'D' and o == 'C':
            dc += 1
        else:
            dd += 1

    opp_def = n - opp_c
    recent_len = 10 if n >= 10 else n
    recent_op = op[-recent_len:]
    recent_def = 0
    for x in recent_op:
        if x == 'D':
            recent_def += 1
    recent_coop = recent_len - recent_def

    last_me, last_op = history[-1]

    # Trap detection: if we have been cooperating while opponent repeatedly defects
    # early, avoid falling into a permanent exploitation loop.
    if n >= 10 and cd >= 4 and dc == 0 and recent_def >= 6:
        return 'D'

    # Against unconditional cooperation, cooperate most of the time.
    if opp_def == 0:
        if n >= 96:
            return 'D'
        return 'C'

    # Against sustained defection, defect.
    if opp_def >= n - 1 and n >= 5:
        return 'D'

    # Strong patterns of defection.
    if recent_def >= 8:
        return 'D'
    if opp_def * 2 >= n and n >= 12:
        if rng.random() < 0.8:
            return 'D'
        return 'C'

    # Recover from a defection episode: if opponent mostly cooperates and last was C.
    if last_op == 'C' and recent_def <= 2:
        return 'C'

    # If opponent just defected after our cooperation, retaliate, but avoid over-punishing
    # an otherwise cooperative opponent.
    if last_op == 'D' and last_me == 'C':
        if opp_def * 5 <= n and n >= 20:
            if rng.random() < 0.25:
                return 'C'
        return 'D'

    # If we defected and opponent cooperated, typically return to cooperation.
    if last_op == 'C' and last_me == 'D':
        return 'C'

    # If both defect, continue defecting unless opponent has been decent and we need recovery.
    if last_op == 'D' and last_me == 'D':
        if opp_def * 3 <= n and rng.random() < 0.2:
            return 'C'
        return 'D'

    # Periodic opponent pattern: defections at positions congruent to 1,2 mod 5.
    if n >= 8:
        pattern_score = 0
        for i in range(max(0, n - 15), n):
            if (i % 5) in (0, 1):
                if op[i] == 'D':
                    pattern_score += 1
            else:
                if op[i] == 'C':
                    pattern_score += 1
        if pattern_score >= 12 and rng.random() < 0.8:
            return 'D'

    # Endgame: take advantage of very cooperative opponents.
    if n >= 95:
        if opp_def * 4 <= n:
            return 'D'
        if last_op == 'D':
            return 'D'
        return 'C'

    # Generally cooperate.
    return 'C'
